+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.core.ui.MainLayout;
+import ai.unifiedprocess.petclinic.vet.domain.Vet;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.data.provider.DataProvider;
+import com.vaadin.flow.data.provider.Query;
+import com.vaadin.flow.router.NavigationTrigger;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+
+import java.util.stream.Stream;
+
+/** UC-002: View Veterinarians, with rows fetched as the visitor scrolls. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VetsView extends VerticalLayout {
+
+    private final transient VetRepository repository;
+    private final Grid<Vet> grid;
+    private boolean failed;
+
+    public VetsView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+
+        grid = new Grid<>();
+        grid.setSizeFull();
+        grid.setSelectionMode(Grid.SelectionMode.NONE);
+        grid.addColumn(Vet::firstName).setHeader("First Name");
+        grid.addColumn(Vet::lastName).setHeader("Last Name");
+        grid.addColumn(vet -> vet.specialties().isEmpty()
+                ? "none" : String.join(", ", vet.specialties())).setHeader("Specialties");
+        grid.setDataProvider(DataProvider.fromCallbacks(this::fetch, this::count));
+
+        add(new H2("Veterinarians"), grid);
+        expand(grid);
+    }
+
+    private Stream<Vet> fetch(Query<Vet, Void> query) {
+        if (failed) {
+            return Stream.empty();
+        }
+        try {
+            return repository.findPage(query.getOffset(), query.getLimit());
+        } catch (RuntimeException exception) {
+            showError(exception);
+            return Stream.empty();
+        }
+    }
+
+    private int count(Query<Vet, Void> query) {
+        if (failed) {
+            return 0;
+        }
+        try {
+            return repository.count();
+        } catch (RuntimeException exception) {
+            showError(exception);
+            return 0;
+        }
+    }
+
+    private void showError(RuntimeException exception) {
+        failed = true;
+        grid.setVisible(false);
+        UI ui = UI.getCurrent();
+        // Scroll requests run after navigation, outside the router's exception
+        // handling. Finish the grid callback before routing to the error view.
+        ui.beforeClientResponse(ui, context -> ui.getInternals().getRouter()
+                .handleExceptionNavigation(ui, ui.getInternals().getActiveViewLocation(),
+                        exception, NavigationTrigger.PROGRAMMATIC, null));
+    }
+}
